create type public.agreement_status as enum ('draft','legal_review','active','retired');
create type public.checklist_kind as enum ('pre_use','post_use','cleaning','temperature','incident');
create table public.platform_staff (user_id uuid primary key references public.profiles(id) on delete cascade, role text not null check(role in('owner','admin','reviewer')), created_at timestamptz not null default now());
create table public.agreement_versions (id uuid primary key default gen_random_uuid(), agreement_type text not null default 'renter_use', version text not null, title text not null, body_markdown text not null, jurisdiction text, status public.agreement_status not null default 'draft', effective_at timestamptz, created_at timestamptz not null default now(), unique(agreement_type,version));
create unique index one_active_agreement_per_type on public.agreement_versions(agreement_type) where status='active';
create table public.agreement_acceptances (id uuid primary key default gen_random_uuid(), agreement_version_id uuid not null references public.agreement_versions(id), user_id uuid not null references public.profiles(id), business_id uuid not null references public.businesses(id), booking_id uuid references public.bookings(id), signed_name text not null, attestations jsonb not null, agreement_sha256 text not null, ip_address inet, user_agent text, accepted_at timestamptz not null default now());
create table public.kitchen_requirements (id uuid primary key default gen_random_uuid(), kitchen_id uuid not null references public.kitchens(id) on delete cascade, credential_type text not null, minimum_coverage_cents bigint, required boolean not null default true, unique(kitchen_id,credential_type));
create table public.booking_checklists (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, kind public.checklist_kind not null, completed_by uuid not null references public.profiles(id), items jsonb not null, notes text, completed_at timestamptz not null default now());
create table public.equipment_condition_reports (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, resource_id uuid not null references public.equipment_resources(id), reported_by uuid not null references public.profiles(id), condition text not null check(condition in('acceptable','damaged','unsafe','out_of_service')), description text, photo_paths text[] not null default '{}', created_at timestamptz not null default now());
create table public.incident_reports (id uuid primary key default gen_random_uuid(), booking_id uuid references public.bookings(id), kitchen_id uuid not null references public.kitchens(id), reported_by uuid not null references public.profiles(id), incident_type text not null, description text not null, people_involved jsonb not null default '[]', emergency_services_called boolean not null default false, photo_paths text[] not null default '{}', occurred_at timestamptz not null, created_at timestamptz not null default now());
create table public.access_events (id bigint generated always as identity primary key, kitchen_id uuid not null references public.kitchens(id), booking_id uuid references public.bookings(id), user_id uuid not null references public.profiles(id), event_type text not null check(event_type in('access_granted','check_in','check_out','access_denied')), occurred_at timestamptz not null default now(), details jsonb not null default '{}');
alter table public.bookings add column agreement_acceptance_id uuid references public.agreement_acceptances(id), add column security_deposit_cents integer not null default 0 check(security_deposit_cents>=0), add column cleaning_fee_cents integer not null default 0 check(cleaning_fee_cents>=0), add column risk_status text not null default 'not_cleared' check(risk_status in('not_cleared','cleared','blocked'));
create or replace function private.is_platform_staff() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_staff where user_id=(select auth.uid())); $$;
revoke all on function private.is_platform_staff() from public, anon; grant execute on function private.is_platform_staff() to authenticated;
create or replace function private.validate_booking_confirmation() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='confirmed' and old.status is distinct from 'confirmed' then if new.agreement_acceptance_id is null then raise exception 'Current renter agreement acceptance is required'; end if; if not exists(select 1 from public.agreement_acceptances a join public.agreement_versions v on v.id=a.agreement_version_id where a.id=new.agreement_acceptance_id and a.booking_id=new.id and a.business_id=new.renter_business_id and v.status='active' and v.effective_at<=now()) then raise exception 'Agreement acceptance is invalid or outdated'; end if; if exists(select 1 from public.kitchen_requirements kr where kr.kitchen_id=new.kitchen_id and kr.required and not exists(select 1 from public.credentials c where c.business_id=new.renter_business_id and c.credential_type=kr.credential_type and c.status='approved' and (c.expires_on is null or c.expires_on>=current_date))) then raise exception 'Required credential is missing, expired, or unapproved'; end if; new.risk_status='cleared'; end if; return new; end; $$;
revoke all on function private.validate_booking_confirmation() from public, anon, authenticated;
create trigger booking_confirmation_guard before update of status on public.bookings for each row execute function private.validate_booking_confirmation();
alter table public.platform_staff enable row level security; alter table public.agreement_versions enable row level security; alter table public.agreement_acceptances enable row level security; alter table public.kitchen_requirements enable row level security; alter table public.booking_checklists enable row level security; alter table public.equipment_condition_reports enable row level security; alter table public.incident_reports enable row level security; alter table public.access_events enable row level security;
create policy agreement_versions_read on public.agreement_versions for select to authenticated using(status in('active','legal_review') or private.is_platform_staff());
create policy agreement_acceptances_read on public.agreement_acceptances for select to authenticated using(user_id=(select auth.uid()) or private.is_platform_staff());
create policy agreement_acceptances_insert on public.agreement_acceptances for insert to authenticated with check(user_id=(select auth.uid()) and private.is_business_member(business_id));
create policy requirements_read on public.kitchen_requirements for select to authenticated using(true);
create policy requirements_owner_manage on public.kitchen_requirements for all to authenticated using(exists(select 1 from public.kitchens k where k.id=kitchen_id and private.is_business_member(k.owner_business_id)) or private.is_platform_staff()) with check(exists(select 1 from public.kitchens k where k.id=kitchen_id and private.is_business_member(k.owner_business_id)) or private.is_platform_staff());
create policy checklist_participant_read on public.booking_checklists for select to authenticated using(exists(select 1 from public.bookings b where b.id=booking_id and (private.is_business_member(b.renter_business_id) or exists(select 1 from public.kitchens k where k.id=b.kitchen_id and private.is_business_member(k.owner_business_id)) or private.is_platform_staff())));
create policy checklist_participant_insert on public.booking_checklists for insert to authenticated with check(completed_by=(select auth.uid()) and exists(select 1 from public.bookings b where b.id=booking_id and private.is_business_member(b.renter_business_id)));
create policy condition_participant_read on public.equipment_condition_reports for select to authenticated using(exists(select 1 from public.bookings b where b.id=booking_id and (private.is_business_member(b.renter_business_id) or private.is_platform_staff())));
create policy condition_renter_insert on public.equipment_condition_reports for insert to authenticated with check(reported_by=(select auth.uid()) and exists(select 1 from public.bookings b where b.id=booking_id and private.is_business_member(b.renter_business_id)));
create policy incidents_participant_read on public.incident_reports for select to authenticated using(reported_by=(select auth.uid()) or private.is_platform_staff() or exists(select 1 from public.kitchens k where k.id=kitchen_id and private.is_business_member(k.owner_business_id)));
create policy incidents_insert on public.incident_reports for insert to authenticated with check(reported_by=(select auth.uid()));
create policy access_self_read on public.access_events for select to authenticated using(user_id=(select auth.uid()) or private.is_platform_staff() or exists(select 1 from public.kitchens k where k.id=kitchen_id and private.is_business_member(k.owner_business_id)));
create policy platform_staff_admin_all_profiles on public.profiles for select to authenticated using(private.is_platform_staff());
create policy platform_staff_admin_all_businesses on public.businesses for select to authenticated using(private.is_platform_staff());
create policy platform_staff_admin_all_credentials on public.credentials for all to authenticated using(private.is_platform_staff()) with check(private.is_platform_staff());
create policy platform_staff_admin_all_bookings on public.bookings for all to authenticated using(private.is_platform_staff()) with check(private.is_platform_staff());
create policy platform_staff_audit_read on public.audit_events for select to authenticated using(private.is_platform_staff());
create index agreement_acceptances_user_idx on public.agreement_acceptances(user_id,accepted_at desc);
create index agreement_acceptances_booking_idx on public.agreement_acceptances(booking_id);
create index kitchen_requirements_kitchen_idx on public.kitchen_requirements(kitchen_id);
create index booking_checklists_booking_idx on public.booking_checklists(booking_id,kind);
create index condition_reports_booking_idx on public.equipment_condition_reports(booking_id);
create index incident_reports_kitchen_idx on public.incident_reports(kitchen_id,occurred_at desc);
create index access_events_kitchen_time_idx on public.access_events(kitchen_id,occurred_at desc);
